SELECT 
FROM exam_question


        AND year = #{query.year}


        AND subject_code = #{query.subjectCode}


        AND question_type = #{query.questionType}


        AND difficulty = #{query.difficulty}


        AND chapter_name LIKE CONCAT('%', #{query.chapterName}, '%')


        AND (
            tags_json LIKE CONCAT('%', #{query.knowledgePoint}, '%')
            OR chapter_name LIKE CONCAT('%', #{query.knowledgePoint}, '%')
            OR stem LIKE CONCAT('%', #{query.knowledgePoint}, '%')
        )


        AND (stem LIKE CONCAT('%', #{query.keyword}, '%') OR explanation LIKE CONCAT('%', #{query.keyword}, '%'))


ORDER BY year DESC, question_number ASC
LIMIT #{offset}, #{limit}

